// Full appliance run simulation: start_request -> startup_detected ->
// scheduler_decision -> running -> completed. Mirrors the state transitions
// in ac_handle_start and ac_power_monitor with a mock clock. Uses a local
// jobs store so nothing in global.jobs changes and no MQTT is emitted.
const cfg = { spike_limit_w: 4000, startup_w: 50, completion_w: 20 };
const name = 'dishwasher';
const requested_at = new Date('2026-04-14T13:00:00+02:00').getTime();
const deadline = new Date('2026-04-14T22:00:00+02:00').getTime();
const runtime_min = 90;
const max_power_w = 1500;
const pv_now = 3500; // strong midday PV exceeds load -> pv_cover_now path

const jobs = {};
const timeline = [];
let clock = requested_at;
function record(step, extra) {
  timeline.push(Object.assign({
    t: new Date(clock).toISOString(),
    step: step,
    state: jobs[name] ? jobs[name].state : null
  }, extra || {}));
}

// ac_handle_start equivalent
jobs[name] = {
  name: name, state: 'requested', deadline: deadline,
  estimated_runtime_min: runtime_min, max_power_w: max_power_w,
  requested_at: requested_at, last_power: 0, defer_count: 0
};
record('start_request');

// scheduler shim: same decision branches ac_scheduler takes at startup.
function runScheduler() {
  const dev = jobs[name];
  if (dev.deadline - runtime_min * 60000 <= clock + 60000) return { decision: 'run_now', reason: 'deadline' };
  if (pv_now >= max_power_w) return { decision: 'run_now', reason: 'pv_cover_now' };
  return { decision: 'run_now', reason: 'cheapest_now' };
}

// ac_power_monitor equivalent
function power(w) {
  const dev = jobs[name];
  dev.last_power = w; dev.last_update = clock;
  if (dev.state === 'requested' && w > cfg.startup_w) {
    dev.state = 'starting_up'; dev.started_at = clock;
    record('startup_detected', { power_w: w });
    const s = runScheduler();
    record('scheduler_decision', s);
    if (s.decision === 'run_now') {
      dev.state = 'running'; dev.scheduled_at = clock;
      record('running');
    }
  } else if ((dev.state === 'running' || dev.state === 'starting_up') && w < cfg.completion_w) {
    dev.completion_since = dev.completion_since || clock;
    if (clock - dev.completion_since > 60000) {
      dev.state = 'completed'; dev.completed_at = clock;
      record('completed', { runtime_actual_min: Math.round((clock - dev.started_at) / 60000) });
    }
  } else if (w >= cfg.completion_w) {
    dev.completion_since = null;
  }
}

// timeline of simulated power readings
clock += 5000;        power(0);    // outlet ON, appliance not yet drawing
clock += 5000;        power(1500); // spike -> starting_up -> scheduler -> running
clock += 30 * 60000;  power(1400); // mid-cycle
clock += 58 * 60000;  power(10);   // completion_since set at 88 min
clock += 30000;       power(10);   // 30s later, still inside 60s window
clock += 40000;       power(10);   // +70s total -> completed

// assertions
const actual = timeline.map(e => e.step);
const expectedSeq = ['start_request','startup_detected','scheduler_decision','running','completed'];
let pass = expectedSeq.every(s => actual.includes(s));
const sched = timeline.find(e => e.step === 'scheduler_decision');
if (!sched || sched.decision !== 'run_now' || sched.reason !== 'pv_cover_now') pass = false;
if (jobs[name].state !== 'completed') pass = false;

node.status({ fill: pass ? 'green' : 'red', shape: 'dot', text: pass ? 'pass' : 'fail' });
return {
  topic: 'test/T5: full appliance run',
  payload: {
    label: 'T5: full appliance run',
    pass: pass,
    expected_sequence: expectedSeq,
    actual_sequence: actual,
    timeline: timeline,
    final_state: jobs[name]
  }
};

// Single choke point for every appliance status message: add a German
// spoken form alongside the structured fields.
const NAMES = {
  dishwasher: 'Geschirrsp\u00fcler',
  washing_machine: 'Waschmaschine',
  air_conditioner: 'Klimaanlage'
};
const PHRASES = {
  requested: 'wartet',
  deferred: 'wartet auf g\u00fcnstigen Strom',
  deferred_wait: 'wartet auf den Start',
  starting_up: 'startet',
  running: 'l\u00e4uft',
  waiting_for_completion: 'ist fast fertig',
  completed: 'ist fertig',
  off: 'ist ausgeschaltet'
};
// Reasons that deserve their own wording; anything not listed here falls back
// to the phrase for the state.
const REASONS = {
  too_warm: 'startet, es ist zu warm',
  temp_reached: 'schaltet ab, es ist k\u00fchl genug',
  pv_low: 'schaltet ab, es gibt zu wenig Solarstrom',
  startup_timeout: 'wurde nicht gestartet, die Steckdose ist wieder aus'
};

let p = msg.payload;
if (typeof p === 'string') { try { p = JSON.parse(p); } catch (e) { return msg; } }
if (!p || typeof p !== 'object') return msg;

// "noch 2 Stunden und 23 Minuten" - spoken German, so 1 becomes "eine".
function restlaufzeit(iso) {
  const end = iso ? new Date(iso).getTime() : NaN;
  if (isNaN(end)) return null;
  const total = Math.round((end - Date.now()) / 60000);
  if (total <= 0) return null;
  const h = Math.floor(total / 60);
  const m = total % 60;
  const parts = [];
  if (h === 1) { parts.push('eine Stunde'); } else if (h > 1) { parts.push(h + ' Stunden'); }
  if (m === 1) { parts.push('eine Minute'); } else if (m > 1) { parts.push(m + ' Minuten'); }
  if (!parts.length) return 'weniger als eine Minute';
  return parts.join(' und ');
}

// 27.5 is spoken "27,5 Grad".
function grad(v) { return String(v).replace('.', ',') + ' Grad'; }

const device = NAMES[p.device];
let phrase = REASONS[p.reason] || PHRASES[p.state];
if (p.state === 'running' && !REASONS[p.reason]) {
  const rest = restlaufzeit(p.predicted_end_at);
  phrase = rest ? 'l\u00e4uft noch ' + rest : 'l\u00e4uft';
} else if (p.reason === 'no_telemetry') {
  phrase = 'meldet keinen Stromverbrauch, die Steckdose bleibt an';
} else if (p.reason === 'outside_cool') {
  phrase = 'schaltet ab, drau\u00dfen sind es nur ' + grad(p.outside_c) + ', besser l\u00fcften';
} else if (p.state === 'config') {
  // Read back only what was actually set; a reset has no `changed` and reads all of it.
  const ch = Array.isArray(p.changed) ? p.changed : Object.keys(p);
  const bits = [];
  if (ch.indexOf('temp_on_c') !== -1 || ch.indexOf('temp_off_c') !== -1) {
    bits.push('startet ab ' + grad(p.temp_on_c) + ' und stoppt unter ' + grad(p.temp_off_c));
  }
  if (ch.indexOf('temp_outside_off_c') !== -1) {
    bits.push('bleibt aus, solange es drau\u00dfen h\u00f6chstens ' + grad(p.temp_outside_off_c) + ' hat');
  }
  phrase = bits.join(', und ');
} else if (p.state === 'config_rejected') {
  phrase = 'hat die Einstellung nicht angenommen';
}
if (device && phrase) { p.voice = device + ' ' + phrase; }

msg.payload = p;
return msg;

const FAST_S = 10;
const RATES = {
  requested: 'fast',
  starting_up: 'fast',
  running: 'fast',
  waiting_for_completion: 'fast',
  deferred_wait: 'fast',
  deferred: 'normal',
  completed: 'normal',
  off: 'normal'
};
const DEVICES = {
  washing_machine: { kind: 'z2m', id: '0x70b3d52b6013d856', normal_s: 30 },
  dishwasher: { kind: 'tasmota', id: 'OgKuGsp', normal_s: 300 },
  air_conditioner: { kind: 'tasmota', id: 'OgWzKli', normal_s: 300 }
};

function command(name, rate) {
  const dev = DEVICES[name];
  const seconds = rate === 'fast' ? FAST_S : dev.normal_s;
  if (dev.kind === 'tasmota') {
    return { topic: 'tm/cmnd/' + dev.id + '/TelePeriod', payload: String(seconds) };
  }
  return {
    topic: 'z2m/bridge/request/device/options',
    payload: JSON.stringify({ id: dev.id, options: { measurement_poll_interval: seconds } })
  };
}

// On startup the devices keep whatever rate they had before the restart, while
// flow context has been lost. Re-assert the rate each device should be at.
// NB: the flag cannot be called msg.reset - that is a control property the
// delay node upstream consumes to flush its queue.
if (msg.tele_reset === true) {
  const jobs = global.get('jobs') || {};
  const applied = {};
  for (const name of Object.keys(DEVICES)) {
    const job = jobs[name];
    const rate = (job && RATES[job.state]) || 'normal';
    applied[name] = rate;
    node.send(command(name, rate));
  }
  flow.set('tele_rate', applied);
  node.status({ fill: 'blue', shape: 'ring', text: 'reset ' + JSON.stringify(applied) });
  return null;
}

const parts = (msg.topic || '').split('/');
if (parts.length < 4 || parts[0] !== 'home' || parts[1] !== 'appliance' || parts[3] !== 'status') return null;
const name = parts[2];
if (!DEVICES[name]) {
  node.warn('sampling rate: unknown device ' + name);
  return null;
}

let p = msg.payload;
if (typeof p === 'string') {
  try { p = JSON.parse(p); } catch (e) { return null; }
}
const rate = RATES[p && p.state];
if (!rate) return null;

const applied = flow.get('tele_rate') || {};
if (applied[name] === rate) return null;
applied[name] = rate;
flow.set('tele_rate', applied);

node.status({ fill: rate === 'fast' ? 'green' : 'grey', shape: 'dot', text: name + ' ' + rate });
return command(name, rate);

// Temperature/PV thermostat for the air conditioner. Every other appliance here
// is started by the user; the AC decides for itself from the inside temperature
// and the PV surplus, then goes through the same start/stop command handler.
function localDay(ms){const d=new Date(ms);const pad=n=>String(n).padStart(2,'0');return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate());}
const NAME = 'air_conditioner';
const cfg = flow.get('config') || {};
// `thermostat config` may override the temperatures at runtime.
const th = Object.assign({}, cfg.ac_thermostat || {}, flow.get('ac_thermostat_cfg', 'file') || {});
const temp_on = th.temp_on_c != null ? th.temp_on_c : 27;
const temp_off = th.temp_off_c != null ? th.temp_off_c : 26;
const pv_min = th.pv_min_w != null ? th.pv_min_w : 1200;
const pv_low_dwell = th.pv_low_dwell_ms != null ? th.pv_low_dwell_ms : 5 * 60000;

// "weather" is written to the file context store by the weather flow:
// eco_in is the inside temperature, temp the outside one.
const w = global.get('weather', 'file') || global.get('weather') || {};
const temp = Number(w.eco_in);
if (isNaN(temp)) {
  node.status({ fill: 'grey', shape: 'ring', text: 'no eco_in' });
  return null;
}

// Cool outside: stop a run and hold off starting one - open a window instead.
// Without the margin the AC would cycle while the reading sits on the mark.
// An unknown outside temperature simply does not veto anything.
const outside = Number(w.temp);
const outside_max = th.temp_outside_off_c != null ? th.temp_outside_off_c : 25;
const outside_margin = th.outside_hysteresis_c != null ? th.outside_hysteresis_c : 0.5;
const outside_cool = !isNaN(outside) && outside <= outside_max;
const outside_warm_enough = isNaN(outside) || outside > outside_max + outside_margin;
const pv = Math.max(0, Number((global.get('ess') || {}).pac) || 0);
const now = Date.now();

// Stopping on PV needs the dip to persist, otherwise every cloud cycles the
// compressor. Starting uses the live value - waiting there costs nothing.
const pvOk = pv >= pv_min;
let pvState = flow.get('ac_pv_state');
if (!pvState || pvState.ok !== pvOk) {
  pvState = { ok: pvOk, since: now };
  flow.set('ac_pv_state', pvState);
}
const pvLowSustained = !pvOk && (now - pvState.since) >= pv_low_dwell;

const jobs = global.get('jobs') || {};
const job = jobs[NAME];
const active = !!job && job.state !== 'completed';

// A run that ended without this node asking for it means the unit was turned
// off by hand - the plug button, its own remote (the power monitor then
// completes the job), or a stop command. Either way, no auto start today.
// A stop command is caught in `handle command`, which sees it even when no
// job was running.
if (flow.get('ac_thermo_was_active') === true && !active) {
  flow.set('ac_manual_off_day', localDay(now), 'file');
}
const locked_out = flow.get('ac_manual_off_day', 'file') === localDay(now);

let cmd = null;
let reason = null;
let details = null;
if (active) {
  if (temp < temp_off) { cmd = false; reason = 'temp_reached'; }
  else if (outside_cool) { cmd = false; reason = 'outside_cool'; details = { outside_c: outside }; }
  else if (pvLowSustained) { cmd = false; reason = 'pv_low'; }
} else if (temp >= temp_on && pvOk && outside_warm_enough && !locked_out) {
  cmd = true;
  reason = 'too_warm';
}

// Remember what the run state will be once the command has been handled, so
// the next tick can tell an outside stop from one of ours.
flow.set('ac_thermo_was_active', cmd === null ? active : cmd);

const info = temp.toFixed(1) + (isNaN(outside) ? '' : '/' + outside.toFixed(1)) + '°C ' + Math.round(pv) + 'W';
if (cmd === null) {
  const idle = locked_out ? 'off today ' : 'idle ';
  node.status({ fill: active ? 'green' : 'grey', shape: 'dot', text: (active ? job.state + ' ' : idle) + info });
  return null;
}
node.status({ fill: cmd ? 'green' : 'blue', shape: 'dot', text: reason + ' ' + info });
const out = { on: cmd, reason: reason, src: 'thermostat' };
if (details) out.details = details;
return { topic: 'red/appliance/' + NAME, payload: out };

function localDay(ms){const d=new Date(ms);const pad=n=>String(n).padStart(2,'0');return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate());}
// The outlet is on and the appliance never started drawing power: nobody
// pressed start, or the AC is off at its own remote. Cut the outlet again
// instead of leaving it live for the rest of the day.
const WAITING = { requested: true, deferred_wait: true };
const cfg = flow.get('config') || {};
const jobs = global.get('jobs') || {};
const now = Date.now();
const switches = [];
const statuses = [];
let dirty = false;

for (const name of Object.keys(jobs)) {
  const dev = jobs[name];
  if (!dev || !WAITING[dev.state]) continue;
  const per = (cfg.appliances && cfg.appliances[name]) || {};
  const limit_min = per.startup_timeout_min != null ? per.startup_timeout_min : (cfg.startup_timeout_min || 30);
  const since = dev.waiting_since || dev.requested_at || now;
  const waited_min = Math.round((now - since) / 60000);
  if (waited_min < limit_min) continue;

  // Not a single reading since the outlet went on. A running appliance
  // reports its draw and an idle one reports zero, so silence means the
  // plug is not talking to us - cutting the outlet on that guess would
  // stop a machine that is very much running. Say it once and leave it be.
  if (!(dev.last_update > since)) {
    if (!dev.telemetry_warned) {
      dev.telemetry_warned = true;
      dirty = true;
      statuses.push({
        topic: 'home/appliance/' + name + '/status',
        payload: { state: dev.state, reason: 'no_telemetry', device: name, waited_min: waited_min },
        retain: true
      });
      node.warn(name + ': no power readings at all within ' + waited_min
                + ' min, leaving the outlet on - check the meter');
    }
    continue;
  }

  delete jobs[name];
  // Nothing ran, so the thermostat would just ask again on its next tick.
  // Treat it like an off by hand and leave the AC alone for the rest of the day.
  if (name === 'air_conditioner') flow.set('ac_manual_off_day', localDay(now), 'file');

  switches.push({ topic: 'home/outlet/' + name + '/set', payload: 'OFF' });
  statuses.push({
    topic: 'home/appliance/' + name + '/status',
    payload: { state: 'off', reason: 'startup_timeout', device: name, waited_min: waited_min },
    retain: true
  });
  node.warn(name + ': no power draw within ' + limit_min + ' min, switching the outlet off');
}

if (!switches.length && !dirty) return null;
global.set('jobs', jobs);
const cut = statuses.filter(s => s.payload.reason === 'startup_timeout').map(s => s.payload.device);
const mute = statuses.filter(s => s.payload.reason === 'no_telemetry').map(s => s.payload.device);
node.status({
  fill: 'yellow',
  shape: cut.length ? 'dot' : 'ring',
  text: (cut.length ? 'timeout: ' + cut.join(', ') + ' ' : '') + (mute.length ? 'no telemetry: ' + mute.join(', ') : '')
});
return [switches, statuses];

// Runtime overrides for the AC thermostat temperatures:
//   red/appliance/air_conditioner/config  {"temp_on_c":28,"temp_off_c":26}
//   red/appliance/air_conditioner/config  {"temp_outside_off_c":24}
//   red/appliance/air_conditioner/config  28          -> temp_on_c, temp_off_c
//                                                        follows at the same gap
//   red/appliance/air_conditioner/config  default     -> back to cfg defaults
// Kept in the file context store, so they outlive a restart; whatever is not
// set here stays at the default from `init config`.
const LIMITS = { temp_on_c: [5, 35], temp_off_c: [5, 35], temp_outside_off_c: [0, 40] };
const cfg = flow.get('config') || {};
const base = cfg.ac_thermostat || {};
const stored = flow.get('ac_thermostat_cfg', 'file') || {};

function answer(state, extra) {
  return {
    topic: 'home/appliance/air_conditioner/status',
    payload: Object.assign({ state: state, device: 'air_conditioner' }, extra),
    // Not retained: the retained status topic must keep showing the run state.
    retain: false
  };
}
function reject(why) {
  node.warn('thermostat config: ' + why);
  node.status({ fill: 'red', shape: 'ring', text: why });
  return answer('config_rejected', { reason: why });
}

let p = msg.payload;
if (Buffer.isBuffer(p)) p = p.toString();
if (typeof p === 'string') {
  const s = p.trim();
  if (s === '' || s.toLowerCase() === 'default' || s.toLowerCase() === 'reset') {
    flow.set('ac_thermostat_cfg', null, 'file');
    node.status({ fill: 'grey', shape: 'dot', text: 'defaults' });
    return answer('config', { temp_on_c: base.temp_on_c, temp_off_c: base.temp_off_c,
                              temp_outside_off_c: base.temp_outside_off_c });
  }
  if (/^-?\d+([.,]\d+)?$/.test(s)) p = Number(s.replace(',', '.'));
  else { try { p = JSON.parse(s); } catch (e) { return reject('bad payload'); } }
}
// A bare number is "run it warmer/cooler": it moves the whole band and keeps
// the gap, so a single value can never land below the stop temperature.
let shift_band = false;
if (typeof p === 'number') { p = { temp_on_c: p }; shift_band = true; }
if (!p || typeof p !== 'object' || Array.isArray(p)) return reject('bad payload');

const prev = Object.assign({}, base, stored);
const next = Object.assign({}, prev);
const keys = Object.keys(p);
if (!keys.length) return reject('nothing to set');
for (const key of keys) {
  if (!LIMITS[key]) return reject('unknown setting ' + key);
  const v = Number(p[key]);
  if (isNaN(v)) return reject('not a number: ' + key);
  next[key] = v;
}
if (shift_band) {
  const gap = prev.temp_on_c - prev.temp_off_c > 0 ? prev.temp_on_c - prev.temp_off_c : 1;
  next.temp_off_c = Math.round((next.temp_on_c - gap) * 10) / 10;
}
for (const key of Object.keys(LIMITS)) {
  if (next[key] < LIMITS[key][0] || next[key] > LIMITS[key][1]) return reject('out of range: ' + key);
}
// Without a gap between the two the AC would chatter around a single value.
if (!(next.temp_off_c < next.temp_on_c)) return reject('temp_off_c must stay below temp_on_c');

const save = {};
for (const key of Object.keys(LIMITS)) { if (next[key] != null) save[key] = next[key]; }
flow.set('ac_thermostat_cfg', save, 'file');
node.status({ fill: 'green', shape: 'dot', text: 'on ' + next.temp_on_c + ' / off ' + next.temp_off_c
                                                 + ' / out ' + next.temp_outside_off_c });
// `changed` tells the voice message which half to read back.
return answer('config', Object.assign({ changed: keys }, save));
